workbox_routing_registerRoute(/\.(js|css|woff|woff2|ttf|eot)$/, new workbox_strategies_StaleWhileRevalidate({ "cacheName":"static-resources", plugins: [new workbox_expiration_ExpirationPlugin({ maxEntries: 100, maxAgeSeconds: 604800 })] }), 'GET');




